-- READ ONLY: catalog/projection metadata only. Select the exact SLM project before execution.
select jsonb_build_object(
 'history_columns',(select jsonb_agg(column_name order by ordinal_position) from information_schema.columns where table_schema='supabase_migrations' and table_name='schema_migrations'),
 'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force',c.relforcerowsecurity) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname like 'slm_%' and c.relkind='r'),
 'policies',(select jsonb_agg(to_jsonb(p) order by p.tablename,p.policyname) from pg_policies p where (p.schemaname='public' and p.tablename like 'slm_%') or p.schemaname='storage'),
 'routines',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl,'definition_md5',md5(pg_get_functiondef(p.oid)),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE')) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prokind='f' and (n.nspname='slm_private' or (n.nspname='public' and (p.proname like 'slm_%' or p.proname like 'current_session%' or p.proname like 'is_%')))),
 'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid))) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and ((n.nspname='public' and c.relname like 'slm_%') or n.nspname='auth')),
 'grants',(select jsonb_agg(to_jsonb(g) order by table_name,grantee,privilege_type) from information_schema.role_table_grants g where g.table_schema='public' and g.table_name like 'slm_%' and g.grantee in ('anon','authenticated','PUBLIC')),
 'bucket',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)) from storage.buckets where id='slm-profile-photos'),
 'columns',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname='public' and c.relname like 'slm_%' and c.relkind='r' and a.attnum>0 and not a.attisdropped),
 'constraints',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',o.conname,'definition',pg_get_constraintdef(o.oid)) order by c.relname,o.conname) from pg_constraint o join pg_class c on c.oid=o.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname like 'slm_%'),
 'indexes',(select jsonb_agg(jsonb_build_object('table',tablename,'name',indexname,'definition',indexdef) order by tablename,indexname) from pg_indexes where schemaname='public' and tablename like 'slm_%'),
 'extensions',(select jsonb_agg(jsonb_build_object('name',extname,'schema',n.nspname,'version',extversion)) from pg_extension e join pg_namespace n on n.oid=e.extnamespace where extname in ('pgcrypto','uuid-ossp','pg_net'))
) as audit;
